package com.shoply.infrastructure.persistence;
import com.shoply.domain.model.*; import com.shoply.domain.repository.CartRepository; import com.shoply.infrastructure.persistence.entity.*; import com.shoply.infrastructure.persistence.repository.SpringDataCartRepository; import java.util.*; import org.springframework.stereotype.Repository;
@Repository public class CartPersistenceAdapter implements CartRepository { private final SpringDataCartRepository carts; public CartPersistenceAdapter(SpringDataCartRepository carts){this.carts=carts;} public Optional<Cart> findByCustomerId(UUID id){return carts.findByUserId(id).map(this::domain);} public Cart save(Cart cart){CartEntity entity=carts.findByUserId(cart.customerId()).orElseGet(()->new CartEntity(cart.id(),cart.customerId()));entity.getItems().clear();cart.items().forEach(i->entity.getItems().add(new CartItemEntity(entity,i.productId(),i.quantity())));return domain(carts.save(entity));} private Cart domain(CartEntity e){return new Cart(e.getId(),e.getUserId(),e.getItems().stream().map(i->new CartItem(i.getProductId(),i.getQuantity())).toList());} }
